def solve(record):
    x = record['record_1']

    # Sticky caps lock: item codes may have arbitrary letter casing per
    # keystroke. Normalize every code to lowercase before folding so that
    # 'ZX', 'Zx', 'zX' and 'zx' all refer to the same stock code.
    def normalize(code):
        return ''.join(c.lower() if c.isalpha() else c for c in code)

    # Fold [item, signed quantity] transactions into a mapping of
    # net quantities per (normalized) item code.
    net = {}
    for transaction in x:
        code, quantity = transaction[0], transaction[1]
        key = normalize(code)
        net[key] = net.get(key, 0) + quantity

    # Displayed stock is physical inventory; the balance sheet only tracks
    # settled accounts, so items with zero net quantity drop out.
    return {code: qty for code, qty in net.items() if qty != 0}
