from collections import deque


def solve(record):
    x = record['record_3']
    edges, source, target = x[0], x[1], x[2]

    # Trivial case: already at the target.
    if source == target:
        return 0

    # Build a one-way adjacency map.
    # A self-loop (self-transfer at one airport) never advances a route:
    # it is only meaningful as part of a positive-length round trip,
    # so it can never appear on a shortest route and is skipped.
    graph = {}
    for u, v in edges:
        if u == v:
            continue
        graph.setdefault(u, []).append(v)

    # BFS for the fewest edges from source to target.
    visited = {source}
    queue = deque([(source, 0)])
    while queue:
        node, dist = queue.popleft()
        for nxt in graph.get(node, ()):
            if nxt == target:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, dist + 1))

    # Unreachable: feed the signed distance array with a negative marker.
    return -1
